import{_ as e,o as d,c as l,a2 as o}from"./chunks/framework.BUwdTBzS.js";const p=JSON.parse('{"title":"dev-comp","description":"面向 vue-amazing-ui 组件库的单组件开发迭代工作流。轻量领域流程（6 阶段）+ 软复用 dev-flow 生态能力（工作上下文/plan/开发日志/度量/知识沉淀/提交），全程不进入 dev-flow 流程状态机与门控，因此轻量不臃肿。适用于在该组件库中新增或完善单个组件（如Menu/…","frontmatter":{"title":"dev-comp","description":"面向 vue-amazing-ui 组件库的单组件开发迭代工作流。轻量领域流程（6 阶段）+ 软复用 dev-flow 生态能力（工作上下文/plan/开发日志/度量/知识沉淀/提交），全程不进入 dev-flow 流程状态机与门控，因此轻量不臃肿。适用于在该组件库中新增或完善单个组件（如Menu/…"},"headers":[],"relativePath":"skills/dev-comp.md","filePath":"skills/dev-comp.md","lastUpdated":null}'),a={name:"skills/dev-comp.md"};function n(c,t,s,i,r,g){return d(),l("div",null,[...t[0]||(t[0]=[o(`<blockquote><p>📄 本页由源文件 <code>skills/dev-comp/SKILL.md</code> 自动投影生成（单一权威源）。请勿直接编辑本页。</p></blockquote><h1 id="dev-comp" tabindex="-1">dev-comp <a class="header-anchor" href="#dev-comp" aria-label="Permalink to &quot;dev-comp&quot;">​</a></h1><blockquote><p>定位：vue-amazing-ui 单组件开发迭代领域 SOP。 架构：<strong>轻量领域流程 + 软复用 dev-flow 能力模块</strong>。全程❌ 不产生 <code>.flow</code> 锁、❌ 不走 dev-flow 重型门控（<code>.validated</code> 物理检查点 / JSON 逐步校验 / 门控 subagent / post-step 脚本 / 工具门禁）；✅ 仅保留<strong>轻量交互式 Gate</strong>——每阶段完成后输出「阶段完成报告」并弹 <code>ask_followup_question</code>，等用户确认再进入下一阶段（详见「6 阶段 + Gate 流程总览」）；✅ 另配 1 个<strong>轻量校验脚本</strong> <code>scripts/validate-component.sh</code> 承载 Gate 5 确定性检查（设计哲学「确定性用代码」，详见「能力复用索引」）。</p></blockquote><h2 id="⚙️-个人化配置区-复用-分享时只改这一块" tabindex="-1">⚙️ 个人化配置区（复用/分享时只改这一块） <a class="header-anchor" href="#⚙️-个人化配置区-复用-分享时只改这一块" aria-label="Permalink to &quot;⚙️ 个人化配置区（复用/分享时只改这一块）&quot;">​</a></h2><blockquote><p>本 skill 核心流程通用；下列配置<strong>换人换机时只需填 4 个本地路径</strong>，其余保持默认即可。</p></blockquote><h3 id="必填-首次使用前填写-artifacts-fallback-dir-可留空" tabindex="-1">必填（首次使用前填写；<code>ARTIFACTS_FALLBACK_DIR</code> 可留空） <a class="header-anchor" href="#必填-首次使用前填写-artifacts-fallback-dir-可留空" aria-label="Permalink to &quot;必填（首次使用前填写；\`ARTIFACTS_FALLBACK_DIR\` 可留空）&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">配置项</th><th style="text-align:left;">填写你的本地路径</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>PROJECT_ROOT</code></td><td style="text-align:left;"><code>~/myGithub/vue-amazing-ui</code></td><td style="text-align:left;">组件库项目根</td></tr><tr><td style="text-align:left;"><code>REF_ANTDV_LOCAL</code></td><td style="text-align:left;"><code>~/myGithub/ant-design-vue</code></td><td style="text-align:left;">Ant Design Vue 本地 clone 路径（留空则降级用官网）</td></tr><tr><td style="text-align:left;"><code>REF_NAIVE_LOCAL</code></td><td style="text-align:left;"><code>~/myGithub/naive-ui</code></td><td style="text-align:left;">Naive UI 本地 clone 路径（留空则降级用官网）</td></tr><tr><td style="text-align:left;"><code>ARTIFACTS_FALLBACK_DIR</code></td><td style="text-align:left;"><code>~/myGithub/ai-coding-kit/skills/dev-comp/artifacts/</code></td><td style="text-align:left;">产物归档兜底目录（用户将产物归档到 skill 下时使用；留空则仅扫 <code>~/.codebuddy/</code> 运行时目录）</td></tr></tbody></table><h3 id="默认可用-无需修改" tabindex="-1">默认可用（无需修改） <a class="header-anchor" href="#默认可用-无需修改" aria-label="Permalink to &quot;默认可用（无需修改）&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">配置项</th><th style="text-align:left;">当前值</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>REF_ANTDV_GH</code></td><td style="text-align:left;"><a href="https://github.com/vueComponent/ant-design-vue" target="_blank" rel="noreferrer">https://github.com/vueComponent/ant-design-vue</a></td><td style="text-align:left;">Ant Design Vue GitHub</td></tr><tr><td style="text-align:left;"><code>REF_NAIVE_GH</code></td><td style="text-align:left;"><a href="https://github.com/tusen-ai/naive-ui" target="_blank" rel="noreferrer">https://github.com/tusen-ai/naive-ui</a></td><td style="text-align:left;">Naive UI GitHub</td></tr><tr><td style="text-align:left;"><code>REF_ANTDV_DOC</code></td><td style="text-align:left;"><a href="https://www.antdv.com/components/overview-cn/" target="_blank" rel="noreferrer">https://www.antdv.com/components/overview-cn/</a></td><td style="text-align:left;">antdv 官网</td></tr><tr><td style="text-align:left;"><code>REF_NAIVE_DOC</code></td><td style="text-align:left;"><a href="https://www.naiveui.com/zh-CN/os-theme/docs/introduction" target="_blank" rel="noreferrer">https://www.naiveui.com/zh-CN/os-theme/docs/introduction</a></td><td style="text-align:left;">naive 官网</td></tr><tr><td style="text-align:left;"><code>CAP_WORKING_CONTEXT_DIR</code></td><td style="text-align:left;"><code>~/.codebuddy/dev-comp/working-context/</code></td><td style="text-align:left;">工作上下文目录（dev-comp 专属）</td></tr><tr><td style="text-align:left;"><code>CAP_METRICS_DIR</code></td><td style="text-align:left;"><code>~/.codebuddy/dev-comp/metrics/</code></td><td style="text-align:left;">度量报告目录（dev-comp 专属）</td></tr></tbody></table><blockquote><p>本地 clone 不存在时：降级为仅用官网（web_fetch）参考，并提示用户可clone 以获得源码级复用。</p></blockquote><h2 id="📦-产物存储设计原则-2026-08-18-固化-·-2026-08-19-补充归档兜底" tabindex="-1">📦 产物存储设计原则（2026-08-18 固化 · 2026-08-19 补充归档兜底） <a class="header-anchor" href="#📦-产物存储设计原则-2026-08-18-固化-·-2026-08-19-补充归档兜底" aria-label="Permalink to &quot;📦 产物存储设计原则（2026-08-18 固化 · 2026-08-19 补充归档兜底）&quot;">​</a></h2><blockquote><p>决策背景：深入评估过「产物入仓库」方案，被开源仓库 git 污染 + dev-flow 生态路径硬绑定否决。产物<strong>默认</strong>留在 <code>~/.codebuddy/</code>（第 1-5 条，2026-08-18 固化）；2026-08-19 按用户决策补充第 6 条——用户可显式选择归档到 skill 下 <code>artifacts/</code> 目录（skill 内置 <code>skills/dev-comp/.gitignore</code> 忽略 <code>artifacts/</code> 内容、保留 <code>artifacts/README.md</code>，私有产物不会污染仓库 git 历史；⚠️ 换仓库分发本 skill 时须连同该 <code>.gitignore</code> 一起复制，否则归档产物有入仓库风险），本小节固化六条原则，防止后续迭代被顺手改回。</p></blockquote><ol><li><strong>产物不入仓库</strong>：vue-amazing-ui 是开源项目，工作上下文/对齐清单/决策记录/度量是个人私有开发过程，进 git 污染公开历史，进 <code>.gitignore</code> 污染所有 fork 者（<strong>用户主动归档到 <code>ARTIFACTS_FALLBACK_DIR</code> 的快照除外</strong>，见第 6 条）</li><li><strong>软复用产物沿用固有约定</strong>：devlog（<code>~/.codebuddy/dev-logs/{YYYYMMDD}_{类型}_{简述}/devlog.md</code>，tech-doc 实际规范，目录名由 tech-doc 生成规则决定，<strong>禁止自拟</strong> <code>&lt;项目&gt;/&lt;分支&gt;/</code> 结构）、knowledge（<code>~/.codebuddy/knowledge/vue-amazing-ui/</code>）路径由被软复用的 tech-doc / knowledge-loop skill 硬编码，改不得也不该改（零硬依赖原则）</li><li><strong>自建产物物理隔离</strong>：工作上下文、metrics 放 dev-comp 专属根目录 <code>~/.codebuddy/dev-comp/</code>（<code>working-context/</code> + <code>metrics/</code> 子目录）。不与 dev-flow 混放，避免被 dev-flow 的 lint 全量扫描 / dashboard 统计 / 度量闸门校验误伤</li><li><strong>命名前缀不变</strong>：<code>vaui-</code> 前缀保留，专属目录内按组件检索不受影响</li><li><strong>目录自举（写前必建）</strong>：<code>~/.codebuddy/dev-comp/</code> 专属目录首次使用不存在，阶段 0 初始化与阶段 5 写 metrics 前必须 <code>mkdir -p</code> 兜底，禁止假设目录已存在</li><li><strong>产物归档与接续兜底（2026-08-19 固化 · 2026-08-20 修订为收尾固定步骤）</strong>：产物<strong>默认留在 <code>~/.codebuddy/</code> 运行时目录</strong>（原位即归档，无需额外动作）；阶段 5 收尾时<strong>必弹 <code>ask_followup_question</code> 由用户决策归档目标（固定步骤，禁止跳过）</strong>——A 保留 <code>~/.codebuddy/</code> 运行时目录（默认）/ B 归档到 <code>ARTIFACTS_FALLBACK_DIR</code> 并删除运行时副本（<strong>禁止双份</strong>，归档保留为快照）。归档到 B 后，阶段 0 接续扫描按「<strong>运行时目录优先 → <code>ARTIFACTS_FALLBACK_DIR</code> 兜底</strong>」两级顺序（详见 <code>references/flow.md</code> 阶段 0），命中归档时复制回运行时目录恢复活跃状态</li></ol><h2 id="触发规则" tabindex="-1">触发规则 <a class="header-anchor" href="#触发规则" aria-label="Permalink to &quot;触发规则&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">信号</th><th style="text-align:left;">行为</th></tr></thead><tbody><tr><td style="text-align:left;"><code>dc:</code>（技能名 <code>dev-comp</code> 也生效）</td><td style="text-align:left;">进入 dev-comp，提示指定组件名</td></tr><tr><td style="text-align:left;"><code>dc: {组件名}</code> / <code>dc: 开发 Menu</code></td><td style="text-align:left;">进入，开发指定组件</td></tr><tr><td style="text-align:left;"><code>dc:status</code> / <code>dc:st</code></td><td style="text-align:left;">查看当前组件进度</td></tr><tr><td style="text-align:left;">仅输入 <code>dc:</code>（无后续）</td><td style="text-align:left;">提示补充组件名</td></tr><tr><td style="text-align:left;"><code>组件开发</code> / <code>开发 {X} 组件</code> / <code>完善 {X} 组件</code> / <code>补全 {X} 组件</code></td><td style="text-align:left;">进入 dev-comp</td></tr><tr><td style="text-align:left;">仅提及组件但无开发意图（如&quot;看看 Menu 怎么实现的&quot;）</td><td style="text-align:left;">不触发，普通对话</td></tr></tbody></table><p><strong>优先级</strong>：incident-triage（告警硬触发）&gt; 用户显式 dev-flow 命令 &gt; dev-comp &gt; 普通对话。 <strong>与 dev-flow 互斥</strong>：用户显式用 <code>dev-flow</code> 命令时走 dev-flow；用 <code>dc:</code> / <code>dev-comp</code> 或组件开发意图时走本 skill。二者不同时激活。</p><h2 id="_6-阶段-gate-流程总览" tabindex="-1">6 阶段 + Gate 流程总览 <a class="header-anchor" href="#_6-阶段-gate-流程总览" aria-label="Permalink to &quot;6 阶段 + Gate 流程总览&quot;">​</a></h2><blockquote><p>术语约定：<strong>antd = Ant Design Vue</strong>（官网 <a href="https://www.antdv.com/" target="_blank" rel="noreferrer">https://www.antdv.com/</a> ），非 React 版 ant.design；本文档中 antdv 与 antd 同义。 每阶段完成后插入一道 🚦 <strong>Gate</strong>：先输出「阶段完成报告」，再弹 <code>ask_followup_question</code>（✅ 继续 / ⏸️ 暂停 / ⬅️ 回退），<strong>未获用户确认不得进入下一阶段</strong>。 「一次性走完」仅指<strong>不分 P1-Pn</strong>（单轮交付），Gate 仍逐阶段必弹，不得跳过。</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>阶段 0  接续/初始化   → 读/建精简工作上下文 + todo plan + 分阶段决策</span></span>
<span class="line"><span>阶段 1  准备          → 分支 + 建目录/配置 + 注册占位</span></span>
<span class="line"><span>阶段 2  组件本体      → 对照antdv/naive 源码开发（先搜索复用项目资产）</span></span>
<span class="line"><span>阶段 3  演示用例      → 完整复制官网用例（顺序一致）+ 双组件对照（src/views/xxx/Index.vue + index.ts）（⚠️ 对照为验收期临时结构，阶段 5 收尾清除）</span></span>
<span class="line"><span>阶段 4  文档          → docs 复用演示页 + 周边文档联动</span></span>
<span class="line"><span>阶段 5  验收收尾      → 配置项终检 + 基线全量勾销 + lint+type-check+浏览器对照 → devlog+metrics+knowledge → smart-commit → 引导发布（合入 main + 构建发布）</span></span></code></pre></div><p><strong>各阶段对应 Gate</strong>：Gate 0 确认组件名/分阶段计划/参考源/项目特有需求 · Gate 1 确认分支/目录/注册骨架 · Gate 2 确认功能 + API 四维/Demo 用例对齐清单 · Gate 3 确认演示页完整复制官网用例（顺序一致）+ 双组件对照 · Gate 4 确认文档完整 · Gate 5 配置项终检 + 基线全量勾销 + 确认验收结果 + 提交。</p><blockquote><p>Gate 报告模板 + 交互式选项定义 → <code>references/flow.md</code> §Gate 门控机制 完整执行规范 → <code>read_file(&quot;references/flow.md&quot;)</code></p></blockquote><h2 id="能力复用索引-软复用-零硬依赖-dev-flow" tabindex="-1">能力复用索引（软复用，零硬依赖 dev-flow） <a class="header-anchor" href="#能力复用索引-软复用-零硬依赖-dev-flow" aria-label="Permalink to &quot;能力复用索引（软复用，零硬依赖 dev-flow）&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">能力</th><th style="text-align:left;">复用方式</th><th style="text-align:left;">何时用</th><th style="text-align:left;">详见</th></tr></thead><tbody><tr><td style="text-align:left;">工作上下文</td><td style="text-align:left;">自建精简版模板</td><td style="text-align:left;">阶段 0 建/接续</td><td style="text-align:left;"><code>templates/working-context-lite.tpl.md</code></td></tr><tr><td style="text-align:left;">plan</td><td style="text-align:left;"><code>todo_write</code> 工具</td><td style="text-align:left;">阶段 0 列计划</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;">开发日志</td><td style="text-align:left;"><code>use_skill(&#39;tech-doc&#39;)</code></td><td style="text-align:left;">阶段 5 收尾</td><td style="text-align:left;"><code>references/capability-reuse.md</code></td></tr><tr><td style="text-align:left;">度量采集</td><td style="text-align:left;">自建精简 YAML</td><td style="text-align:left;">阶段 5 收尾</td><td style="text-align:left;"><code>templates/metrics-lite.tpl.yaml</code></td></tr><tr><td style="text-align:left;">知识沉淀</td><td style="text-align:left;"><code>use_skill(&#39;knowledge-loop&#39;)</code></td><td style="text-align:left;">阶段 2 检索 / 阶段 5 沉淀</td><td style="text-align:left;"><code>references/capability-reuse.md</code></td></tr><tr><td style="text-align:left;">提交</td><td style="text-align:left;"><code>use_skill(&#39;smart-commit&#39;)</code></td><td style="text-align:left;">阶段 5 提交</td><td style="text-align:left;"><code>references/capability-reuse.md</code></td></tr><tr><td style="text-align:left;">交互验收 e2e</td><td style="text-align:left;"><code>use_skill(&#39;e2e-testing&#39;)</code>（可选）</td><td style="text-align:left;">阶段 5 关键交互用例</td><td style="text-align:left;"><code>references/checklists.md</code> §交互操作清单</td></tr><tr><td style="text-align:left;">配置项终检 + 提交红线校验</td><td style="text-align:left;"><code>scripts/validate-component.sh</code>（本 skill 自带）</td><td style="text-align:left;">阶段 5 收尾必跑（Gate 5 数据源）</td><td style="text-align:left;"><code>references/checklists.md</code> §发布前配置项终检</td></tr></tbody></table><blockquote><p>⚠️ 上述被调 skill 缺失时<strong>优雅降级</strong>：跳过该环节并一句话提示用户，不阻断主流程。</p></blockquote><h2 id="按需加载索引" tabindex="-1">按需加载索引 <a class="header-anchor" href="#按需加载索引" aria-label="Permalink to &quot;按需加载索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">场景</th><th style="text-align:left;">加载文件</th></tr></thead><tbody><tr><td style="text-align:left;">执行任一阶段</td><td style="text-align:left;"><code>references/flow.md</code></td></tr><tr><td style="text-align:left;">项目结构/注册链路</td><td style="text-align:left;"><code>references/project-map.md</code></td></tr><tr><td style="text-align:left;">参考源路径 + antdv/naive 取舍</td><td style="text-align:left;"><code>references/reference-sources.md</code></td></tr><tr><td style="text-align:left;">找可复用的项目已有资产</td><td style="text-align:left;"><code>references/reusable-assets.md</code></td></tr><tr><td style="text-align:left;">注册/主题/SSR/周边文档 checklist + 发布前配置项终检</td><td style="text-align:left;"><code>references/checklists.md</code></td></tr><tr><td style="text-align:left;">新增组件联动配置地图（⭐易遗漏点全集）</td><td style="text-align:left;"><code>references/linkage-map.md</code></td></tr><tr><td style="text-align:left;">用例标题/简介描述规范（权威源 + 同步）</td><td style="text-align:left;"><code>references/demo-description.md</code></td></tr><tr><td style="text-align:left;">changelog 编写规范（版本号升级 + 双处同步）</td><td style="text-align:left;"><code>references/changelog-spec.md</code></td></tr><tr><td style="text-align:left;">发布流程（合入 main + 构建发布 + 清理）</td><td style="text-align:left;"><code>references/release-flow.md</code></td></tr><tr><td style="text-align:left;">如何软复用 dev-flow 能力 + 降级</td><td style="text-align:left;"><code>references/capability-reuse.md</code></td></tr></tbody></table><h2 id="核心红线-继承项目规范" tabindex="-1">核心红线（继承项目规范） <a class="header-anchor" href="#核心红线-继承项目规范" aria-label="Permalink to &quot;核心红线（继承项目规范）&quot;">​</a></h2><ul><li>❌ 禁止自动 <code>git commit</code>：commit message仅生成，用户明确选择才提交（用 smart-commit）</li><li>❌ commit 格式：<code>&lt;type&gt;: &lt;description&gt;</code>（<strong>无 scope</strong>，项目 commitlint scope-empty）</li><li>❌ <strong>提交前 git 身份实测</strong>：<code>git config user.name/email</code> 实测值必须与工作上下文 <code>git_identity</code> 一致，不符拦截、用户决策后继续；提交后 <code>git log -1 --format=&#39;%h&#39;</code> 实测 hash 回填（详见 <code>references/flow.md</code> 阶段 5 第 4 步）</li><li>❌ 先搜索后编码：新增能力前先查项目已有资产（<code>references/reusable-assets.md</code>）</li><li>✅ 实现方式复用优先级：项目已有组件/功能/样式/布局/逻辑 &gt; antdv 源码实现 &gt; naive 源码实现 &gt; 自研；<strong>组件库已有的功能/样式/布局/逻辑优先复用，禁止重新开发</strong>（详见 <code>references/reference-sources.md</code>）</li><li>✅ 主题 light/dark 双份；链式访问用可选链 <code>?.</code>；禁 any；SSR 安全（禁裸用 window/document）</li><li>✅ 大组件分阶段交付（P1-Pn），避免半成品</li><li>✅ 验收标准：演示页与antdv/naive 真身并排 1:1 对照（本项目组件在左/上，官网组件在右/下）+ 用例顺序与官网一致 + 浏览器实测（⚠️ 对照仅为验收手段：阶段 3 引入 → 阶段 5 浏览器实测验收 → <strong>验收完成后由阶段 5 第 5 步清除</strong>，演示页回归纯本库组件）</li><li>✅ 清单即验收基线：阶段 2 对齐清单（API 四维 + Demo 用例）+ naive 差异登记 + 阶段 0 项目特有需求 = 阶段 5 验收唯一对账标准，Gate 5 全量回显勾销，❌ 项必带处置码（<code>延后 P{n}</code> / <code>不覆盖（理由）</code> / <code>待用户确认</code>），禁止摘要式报告</li><li>✅ <strong>联动清单即注册基线</strong>：<code>references/linkage-map.md</code> 是「新增组件全量联动点」唯一权威源（含 ⭐ 易遗漏点：resolver 依赖映射 / 组件总数 4 处 / components.d.ts 幽灵声明 / App.vue 孤儿变量）。阶段 1/4/5 逐项勾销，<strong>禁止靠记忆「顺手补几处」</strong>；确定性 grep 自检已收拢于 <code>scripts/validate-component.sh</code>（Gate 5 必跑），宣告完成前必须实测</li><li>✅ <strong>配置项终检即发布基线</strong>：<code>references/checklists.md</code> §发布前配置项终检 是阶段 5 验收时固定配置项（代码注册/文档联动/残留清理/一致性）的唯一权威源，Gate 5 必须全量逐项回显勾销 + grep 自检实测；<strong>埋入阶段（1/4）的检查不能替代终检</strong>，发布前必须全量回检</li><li>✅ <strong>验收完成 ≠ 任务结束</strong>：验收通过后按 <code>references/release-flow.md</code> 引导「合入 main（GitHub PR）→ main 上构建发布（<code>pnpm pub</code>，执行前用户逐条确认）→ 发布后清理（删 feat 分支）」；❌ 严禁在 feat 分支上执行发布；用户本轮不发布则写入工作上下文接续指引</li></ul>`,28)])])}const m=e(a,[["render",n]]);export{p as __pageData,m as default};
